import { test, expect } from '@playwright/test';

test.describe('Stale Data Invalidation After Form Submission', () => {
  const testUrl = 'http://localhost:3000';
  let initialDataTimestamp: string;

  test.beforeEach(async ({ page }) => {
    await page.goto(testUrl);
    // Wait for initial data to load
    await page.waitForLoadState('networkidle');
  });

  test('should invalidate stale data after successful form submission', async ({ page }) => {
    // Get initial data timestamp from the page
    const initialDataElement = await page.getByText(/Data loaded at:/);
    initialDataTimestamp = await initialDataElement.textContent() || '';
    expect(initialDataTimestamp).toBeTruthy();

    // Wait a moment to ensure timestamp would be different
    await page.waitForTimeout(1000);

    // Fill and submit the form
    const nameInput = await page.getByLabel('Name');
    await nameInput.fill('Test User');

    const emailInput = await page.getByLabel('Email');
    await emailInput.fill('test@example.com');

    const submitButton = await page.getByRole('button', { name: /Submit/i });
    await submitButton.click();

    // Wait for the form submission to complete
    await page.waitForLoadState('networkidle');

    // Verify success message appears
    const successMessage = await page.getByText(/Form submitted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify that data has been refreshed (timestamp should be updated)
    const updatedDataElement = await page.getByText(/Data loaded at:/);
    const updatedDataTimestamp = await updatedDataElement.textContent() || '';
    expect(updatedDataTimestamp).not.toBe(initialDataTimestamp);
  });

  test('should clear cached data and reload fresh data after submission', async ({ page }) => {
    // Verify initial data is present
    const initialDataContent = await page.getByText(/User data:/);
    await expect(initialDataContent).toBeVisible();

    const initialContent = await initialDataContent.textContent();
    expect(initialContent).toContain('User data:');

    // Submit form with new data
    const nameInput = await page.getByLabel('Name');
    await nameInput.fill('Updated User');

    const submitButton = await page.getByRole('button', { name: /Submit/i });
    await submitButton.click();

    // Wait for network activity to complete
    await page.waitForLoadState('networkidle');

    // Verify the data has been refreshed
    const refreshedDataContent = await page.getByText(/User data:/);
    const newContent = await refreshedDataContent.textContent();

    // The content should reflect the new submission
    expect(newContent).toContain('Updated User');
  });

  test('should show loading state during data refresh after form submission', async ({ page }) => {
    // Submit the form
    const nameInput = await page.getByLabel('Name');
    await nameInput.fill('Test User');

    const submitButton = await page.getByRole('button', { name: /Submit/i });
    await submitButton.click();

    // Check for loading indicator
    const loadingIndicator = await page.getByText(/Loading/i);
    await expect(loadingIndicator).toBeVisible({ timeout: 5000 });

    // Wait for loading to complete
    await page.waitForLoadState('networkidle');

    // Verify loading indicator is gone
    await expect(loadingIndicator).not.toBeVisible();

    // Verify success state is shown
    const successMessage = await page.getByText(/Form submitted successfully/i);
    await expect(successMessage).toBeVisible();
  });
});
